export const APP_WEBSITE_URL = 'https://60secondsapp.io/';

// Shared links must be public HTTPS URLs, even when generated by a development build.
// Never derive them from localhost, a LAN address, or a custom app scheme.
export function publicShareOrigin(value?: string): string {
  try {
    const url = new URL(value || 'https://events.60secondsapp.io');
    if (url.protocol !== 'https:' || url.username || url.password ||
        url.hostname === 'localhost' || url.hostname.endsWith('.local') ||
        /^[\d.]+$/.test(url.hostname) || url.hostname.includes(':') || !url.hostname.includes('.')) {
      return 'https://events.60secondsapp.io';
    }
    return url.origin;
  } catch { return 'https://events.60secondsapp.io'; }
}
export const APP_SHARE_BASE_URL = publicShareOrigin(process.env.EXPO_PUBLIC_SHARE_BASE_URL);

export const buildVideoShareUrl = (videoId: string) => `${APP_SHARE_BASE_URL}/video/${encodeURIComponent(videoId)}`;

export const APP_PLAY_STORE_URL =
  'https://play.google.com/store/apps/details?id=app.sixtyseconds.nightlife';

export const APP_APP_STORE_URL =
  'https://apps.apple.com/ch/app/60seconds-catch-the-moments/id6756535386?l=en-GB';

export const APP_SHARE_LINKS_MESSAGE = [
  `Website: ${APP_SHARE_BASE_URL}`,
].join('\n');

export const buildEventShareUrl = (eventId: string) => `${APP_SHARE_BASE_URL}/${encodeURIComponent(eventId)}`;
